def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    counts = {}
    for row in g:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)

    # The template is the longest horizontal non-background component.
    template = None
    for r in range(h):
        c = 0
        while c < w:
            if g[r][c] == bg:
                c += 1
                continue
            start = c
            while c < w and g[r][c] != bg:
                c += 1
            vals = g[r][start:c]
            if template is None or len(vals) > len(template[2]):
                template = (r, start, vals[:])
    if template is None:
        return g
    tr, tc, vals = template
    n = len(vals)
    center_offset = n // 2

    # Find isolated non-background pixels; these are the locations to receive
    # a centered copy of the horizontal template.
    seen = set()
    markers = []
    for r in range(h):
        for c in range(w):
            if g[r][c] == bg or (r, c) in seen:
                continue
            q = [(r, c)]
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.pop()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and g[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            if len(comp) == 1 and (r, c) != (tr, tc):
                markers.append((r, c))

    for r, c in markers:
        left = c - center_offset
        for j, value in enumerate(vals):
            x = left + j
            if 0 <= x < w:
                g[r][x] = value
    return g


if __name__ == '__main__':
    pass
